function solve(s, p) {
  const n = s.length, m = p.length;
  const memo = new Map();
  function go(i, j) {
    const key = i * (m + 1) + j;
    if (memo.has(key)) return memo.get(key);
    let res;
    if (j === m) {
      res = (i === n);
    } else if (p[j] === '*') {
      res = go(i, j + 1) || (i < n && go(i + 1, j));
    } else if (i < n && (p[j] === '?' || p[j] === s[i])) {
      res = go(i + 1, j + 1);
    } else {
      res = false;
    }
    memo.set(key, res);
    return res;
  }
  return go(0, 0);
}

function solve(s, p) {
  let i = 0, j = 0, star = -1, mark = 0;
  while (i < s.length) {
    if (j < p.length && (p[j] === '?' || p[j] === s[i])) {
      i++; j++;
    } else if (j < p.length && p[j] === '*') {
      star = j; mark = i; j++;
    } else if (star !== -1) {
      j = star + 1; mark++; i = mark;
    } else {
      return false;
    }
  }
  while (j < p.length && p[j] === '*') j++;
  return j === p.length;
}
